def transform(grid):
    rows, cols = len(grid) // 3, len(grid[0]) // 3
    out = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            values = [grid[r][c] for r in range(3*i, 3*i+3) for c in range(3*j, 3*j+3)]
            colors = [v for v in values if v not in (0, 5)]
            if colors:
                out[i][j] = max(set(colors), key=colors.count)
    return out
